import { useContext } from "react";
import { Contextapi } from "./Contextapi";
import { useNavigate } from "react-router-dom";

function Header() {
    const navigate=useNavigate()
    const{loginname,setloginname}=useContext(Contextapi)
    function handlogout(e){
        localStorage.removeItem('loginname')
        setloginname(localStorage.getItem('loginame'))
navigate('/')
    }
    return ( 
<>
<section id="header">
    <div className="container">
        <div className="row">
            <div className="col-md-4">
                <h2>welcome to{loginname}</h2>
            </div>
            <div className="col-md-8 ">
                <h4><button className="btn btn-success" onClick={(e)=>{handlogout(e)}}>logout</button></h4>
            </div>
        </div>
    </div>

</section>


</>

     );
}

export default Header;
